```python
"""Graph utilities for shortest-path and reachability analysis."""
import heapq
from collections import deque
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Target complexity: O((V+E) log V) using Dijkstra's algorithm.
    """
    if source not in graph.adj or target not in graph.adj:
        return None, []

    # distances[node] = (min_dist, predecessor)
    distances: Dict[int, float] = {node: float('inf') for node in graph.adj}
    predecessors: Dict[int, Optional[int]] = {node: None for node in graph.adj}

    distances[source] = 0.0
    pq = [(0.0, source)]

    while pq:
        d, u = heapq.heappop(pq)

        if d > distances[u]:
            continue

        if u == target:
            break

        for v, weight in graph.adj.get(u, []):
            new_dist = d + weight
            if new_dist < distances[v]:
                distances[v] = new_dist
                predecessors[v] = u
                heapq.heappush(pq, (new_dist, v))

    if distances[target] == float('inf'):
        return None, []

    path = []
    curr = target
    while curr is not None:
        path.append(curr)
        curr = predecessors[curr]
    path.reverse()

    return distances[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Target complexity: O((V+E) log V) using a single Dijkstra pass.
    """
    if source not in graph.adj:
        return {}

    distances: Dict[int, float] = {node: float('inf') for node in graph.adj}
    predecessors: Dict[int, Optional[int]] = {node: None for node in graph.adj}

    distances[source] = 0.0
    pq = [(0.0, source)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > distances[u]:
            continue
        for v, weight in graph.adj.get(u, []):
            new_dist = d + weight
            if new_dist < distances[v]:
                distances[v] = new_dist
                predecessors[v] = u
                heapq.heappush(pq, (new_dist, v))

    result = {}
    for node, dist in distances.items():
        if dist != float('inf'):
            path = []
            curr = node
            while curr is not None:
                path.append(curr)
                curr = predecessors[curr]
            path.reverse()
            result[node] = (dist, path)
    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Target complexity: O(k log V + E) using early-termination Dijkstra.
    """
    if source not in graph.adj:
        return []

    distances = {source: 0.0}
    pq = [(0.0, source)]
    nearest = []

    while pq and len(nearest) < k:
        d, u = heapq.heappop(pq)

        if d > distances.get(u, float('inf')):
            continue

        if u != source:
            nearest.append((u, d))
            if len(nearest) == k:
                break

        for v, weight in graph.adj.get(u, []):
            new_dist = d + weight
            if new_dist < distances.get(v, float('inf')):
                distances[v] = new_dist
                heapq.heappush(pq, (new_dist, v))

    return nearest


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.
    Target complexity: O(V + E) using BFS.
    """
    if source not in graph.adj or target not in graph.adj:
        return False
    if source == target:
        return True

    visited = {source}
    queue = deque([source])

    while queue:
        u = queue.popleft()
        for v, _ in graph.adj.get(u, []):
            if v == target:
                return True
            if v not in visited:
                visited.add(v)
                queue.append(v)
    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).
    Target complexity: O(V + E) using BFS on an undirected representation.
    """
    nodes = list(graph.adj.keys())
    if not nodes:
        return []

    # Build undirected adjacency list for weakly connected components
    undirected_adj = {node: set() for node in nodes}
    for u in nodes:
        for v, _ in graph.adj[u]:
            undirected_adj[u].add(v)
            undirected_adj[v].add(u)

    visited = set()
    components = []

    for node in nodes:
        if node not in visited:
            component = set()
            queue = deque([node])
            visited.add(node)
            while queue:
                u = queue.popleft()
                component.add(u)
                for v in undirected_adj[u]:
                    if v not in visited:
                        visited.add(v)
                        queue.append(v)
            components.append(component)

    return components
